CREATE TYPE "CartStatus" AS ENUM ('ACTIVE','CONVERTED','ABANDONED','EXPIRED');
CREATE TYPE "PromotionType" AS ENUM ('PERCENTAGE','FIXED_AMOUNT');
CREATE TABLE "promotions" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"type" "PromotionType" NOT NULL,"value" DECIMAL(12,2) NOT NULL,"minimum_order_amount" DECIMAL(12,2),"maximum_discount" DECIMAL(12,2),"starts_at" TIMESTAMP(3) NOT NULL,"ends_at" TIMESTAMP(3),"usage_limit" INTEGER,"usage_per_user" INTEGER,"status" "CatalogStatus" NOT NULL DEFAULT 'ACTIVE',"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "promotions_pkey" PRIMARY KEY ("id"));
CREATE TABLE "coupons" ("id" TEXT NOT NULL,"code" TEXT NOT NULL,"promotion_id" TEXT NOT NULL,"usage_limit" INTEGER,"usage_count" INTEGER NOT NULL DEFAULT 0,"starts_at" TIMESTAMP(3) NOT NULL,"expires_at" TIMESTAMP(3),"status" "CatalogStatus" NOT NULL DEFAULT 'ACTIVE',"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "coupons_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "coupons_code_key" ON "coupons"("code");
CREATE TABLE "carts" ("id" TEXT NOT NULL,"uuid" TEXT NOT NULL,"user_id" TEXT,"guest_session_id" TEXT,"status" "CartStatus" NOT NULL DEFAULT 'ACTIVE',"currency" TEXT NOT NULL DEFAULT 'USD',"coupon_id" TEXT,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,"expires_at" TIMESTAMP(3),CONSTRAINT "carts_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "carts_uuid_key" ON "carts"("uuid"); CREATE UNIQUE INDEX "carts_user_id_status_key" ON "carts"("user_id","status"); CREATE UNIQUE INDEX "carts_guest_session_id_status_key" ON "carts"("guest_session_id","status");
CREATE TABLE "wishlists" ("id" TEXT NOT NULL,"user_id" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "wishlists_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "wishlists_user_id_key" ON "wishlists"("user_id");
CREATE TABLE "cart_items" ("id" TEXT NOT NULL,"cart_id" TEXT NOT NULL,"product_id" TEXT NOT NULL,"variant_id" TEXT,"quantity" INTEGER NOT NULL,"unit_price_snapshot" DECIMAL(12,2) NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "cart_items_pkey" PRIMARY KEY ("id"));
CREATE TABLE "wishlist_items" ("id" TEXT NOT NULL,"wishlist_id" TEXT NOT NULL,"product_id" TEXT NOT NULL,"variant_id" TEXT,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "wishlist_items_pkey" PRIMARY KEY ("id"));
ALTER TABLE "coupons" ADD CONSTRAINT "coupons_promotion_id_fkey" FOREIGN KEY ("promotion_id") REFERENCES "promotions"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "carts" ADD CONSTRAINT "carts_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "carts" ADD CONSTRAINT "carts_coupon_id_fkey" FOREIGN KEY ("coupon_id") REFERENCES "coupons"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "cart_items" ADD CONSTRAINT "cart_items_cart_id_fkey" FOREIGN KEY ("cart_id") REFERENCES "carts"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "cart_items" ADD CONSTRAINT "cart_items_product_id_fkey" FOREIGN KEY ("product_id") REFERENCES "products"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "cart_items" ADD CONSTRAINT "cart_items_variant_id_fkey" FOREIGN KEY ("variant_id") REFERENCES "product_variants"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "wishlists" ADD CONSTRAINT "wishlists_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "wishlist_items" ADD CONSTRAINT "wishlist_items_wishlist_id_fkey" FOREIGN KEY ("wishlist_id") REFERENCES "wishlists"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "wishlist_items" ADD CONSTRAINT "wishlist_items_product_id_fkey" FOREIGN KEY ("product_id") REFERENCES "products"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "wishlist_items" ADD CONSTRAINT "wishlist_items_variant_id_fkey" FOREIGN KEY ("variant_id") REFERENCES "product_variants"("id") ON DELETE CASCADE ON UPDATE CASCADE;
